// Letter every element marked data-type="key"; its text stays for screen readers and as a fallback.
window.letter = (el, key) => {
  const t = window.TYPE[key];
  if (!el || !t) return;
  el.classList.add("lettered");
  el.innerHTML = `<span class="sr-only">${t.text}</span><svg class="type" aria-hidden="true" viewBox="${t.viewBox}" style="height:${t.em}em"><path d="${t.d}"/></svg>`;
};
document.querySelectorAll("[data-type]").forEach((el) => window.letter(el, el.dataset.type));
